ALTER TABLE public.visits ADD COLUMN IF NOT EXISTS address_lat double precision,ADD COLUMN IF NOT EXISTS address_lng double precision,ADD COLUMN IF NOT EXISTS check_in_location_reason text,ADD COLUMN IF NOT EXISTS check_out_location_reason text;
CREATE OR REPLACE FUNCTION public.pro_gps_distance(_lat double precision,_lng double precision,_target_lat double precision,_target_lng double precision) RETURNS double precision LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT 6371000*2*asin(sqrt(least(1.0,power(sin(radians(_target_lat-_lat)/2),2)+cos(radians(_lat))*cos(radians(_target_lat))*power(sin(radians(_target_lng-_lng)/2),2)))) $$;
CREATE OR REPLACE FUNCTION public.pro_gps_validate(_visit uuid,_pro uuid,_lat double precision,_lng double precision,_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; d double precision; BEGIN IF NOT public.is_service_caller() THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO v FROM public.visits WHERE id=_visit; IF NOT FOUND OR NOT public.pro_on_cleaning_team_visit(v.id,_pro) THEN RAISE EXCEPTION 'visit_not_assigned'; END IF; IF _lat IS NULL OR _lng IS NULL OR _lat NOT BETWEEN -90 AND 90 OR _lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'invalid_location'; END IF; IF v.address_lat IS NULL OR v.address_lng IS NULL THEN IF length(trim(coalesce(_reason,'')))<10 THEN RETURN jsonb_build_object('ok',false,'error','address_location_unverified_reason_required'); END IF; RETURN jsonb_build_object('ok',true,'location_unverified',true); END IF; d:=public.pro_gps_distance(_lat,_lng,v.address_lat,v.address_lng); IF d>150 AND length(trim(coalesce(_reason,'')))<10 THEN RETURN jsonb_build_object('ok',false,'error','outside_150m_reason_required','distance_meters',round(d::numeric)); END IF; RETURN jsonb_build_object('ok',true,'distance_meters',round(d::numeric)); END $$;
REVOKE ALL ON FUNCTION public.pro_gps_validate(uuid,uuid,double precision,double precision,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pro_gps_validate(uuid,uuid,double precision,double precision,text) TO service_role;
ALTER TABLE public.cleaning_team_presence ADD COLUMN IF NOT EXISTS check_in_location_reason text,ADD COLUMN IF NOT EXISTS check_out_location_reason text;
CREATE OR REPLACE FUNCTION public.pro_gps_visit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.check_in_at IS DISTINCT FROM OLD.check_in_at AND NEW.check_in_at IS NOT NULL THEN IF NEW.address_lat IS NULL OR NEW.address_lng IS NULL OR public.pro_gps_distance(NEW.check_in_lat,NEW.check_in_lng,NEW.address_lat,NEW.address_lng)>150 THEN IF length(trim(coalesce(NEW.check_in_location_reason,'')))<10 THEN RAISE EXCEPTION 'outside_150m_or_unverified_reason_required'; END IF; END IF; END IF; IF NEW.check_out_at IS DISTINCT FROM OLD.check_out_at AND NEW.check_out_at IS NOT NULL THEN IF NEW.address_lat IS NULL OR NEW.address_lng IS NULL OR public.pro_gps_distance(NEW.check_out_lat,NEW.check_out_lng,NEW.address_lat,NEW.address_lng)>150 THEN IF length(trim(coalesce(NEW.check_out_location_reason,'')))<10 THEN RAISE EXCEPTION 'outside_150m_or_unverified_reason_required'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_pro_gps_visit_guard BEFORE UPDATE ON public.visits FOR EACH ROW EXECUTE FUNCTION public.pro_gps_visit_guard();